<div class="box box-success"><div class="box-header with-border"><h3 class="box-title"><i class="fa fa-money"></i> INGRESOS POR EQUIPAJE EXTRA</h3></div><div class="box-body"><form class="form-inline" method="get"><label>Desde</label> <input class="form-control" type="date" name="desde" value="<?php echo htmlspecialchars($desde);?>"> <label>Hasta</label> <input class="form-control" type="date" name="hasta" value="<?php echo htmlspecialchars($hasta);?>"> <button class="btn btn-primary">FILTRAR</button> <button type="button" class="btn btn-default" onclick="window.print()">IMPRIMIR</button></form><hr><table class="table table-bordered table-striped"><thead><tr><th>VIAJE</th><th>FECHA</th><th>RUTA</th><th>FORMA PAGO</th><th>OPERACIONES</th><th>PIEZAS</th><th class="text-right">TOTAL Bs</th></tr></thead><tbody><?php $total=0;foreach($resumen as $r){$total+=(float)$r['total'];?><tr><td><?php echo (int)$r['viaje_id'];?></td><td><?php echo htmlspecialchars($r['viaje_fechasalida']);?></td><td><?php echo htmlspecialchars($r['ruta_nombre']);?></td><td><?php echo htmlspecialchars($r['forma_pago']);?></td><td><?php echo (int)$r['operaciones'];?></td><td><?php echo (int)$r['piezas'];?></td><td class="text-right"><?php echo number_format($r['total'],2);?></td></tr><?php }?></tbody><tfoot><tr><th colspan="6" class="text-right">TOTAL EQUIPAJE EXTRA</th><th class="text-right">Bs <?php echo number_format($total,2);?></th></tr></tfoot></table></div></div>